package vn.iotstar.controller;
import lombok.RequiredArgsConstructor;import jakarta.servlet.http.HttpServletRequest;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;import org.springframework.security.access.prepost.PreAuthorize;import vn.iotstar.service.OrderService;import vn.iotstar.dto.request.ReturnInspectionForm;import vn.iotstar.exception.BadRequestException;import java.math.BigDecimal;
@Controller @RequiredArgsConstructor
public class OrderOperationsController {
 private final OrderService orders;
 private String back(Long id,HttpServletRequest request){return "redirect:"+(request.getRequestURI().startsWith("/admin/")?"/admin":"/staff")+"/orders/"+id;}
 @PostMapping({"/admin/orders/{id}/receive-return","/staff/orders/{id}/receive-return"}) @PreAuthorize("hasAnyRole('ADMIN','STAFF')")
 public String inspect(@PathVariable Long id,@ModelAttribute ReturnInspectionForm form,HttpServletRequest request,RedirectAttributes redirect){try{orders.inspectReturn(id,form);redirect.addFlashAttribute("successMessage","Đã lưu phiếu kiểm đếm; chỉ hàng tốt được nhập kho bán");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return back(id,request);}
 @PostMapping({"/admin/orders/{id}/confirm-delivery","/staff/orders/{id}/confirm-delivery"}) @PreAuthorize("hasAnyRole('ADMIN','STAFF')")
 public String delivery(@PathVariable Long id,@RequestParam BigDecimal collectedAmount,@RequestParam String recipient,@RequestParam(required=false)String note,HttpServletRequest request,RedirectAttributes redirect){try{orders.confirmDelivery(id,collectedAmount,recipient,note);redirect.addFlashAttribute("successMessage","Đã xác nhận giao hàng và số tiền thực thu. Nộp quỹ COD cần đối soát riêng.");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return back(id,request);}
 @PostMapping({"/admin/orders/{id}/pickup-deadline","/staff/orders/{id}/pickup-deadline"}) @PreAuthorize("hasAnyRole('ADMIN','STAFF')")
 public String deadline(@PathVariable Long id,@RequestParam int hours,HttpServletRequest request,RedirectAttributes redirect){try{orders.setPickupDeadline(id,hours);redirect.addFlashAttribute("successMessage","Đã cập nhật hẹn nhận hàng");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return back(id,request);}
 @PostMapping({"/admin/orders/{id}/no-show","/staff/orders/{id}/no-show"}) @PreAuthorize("hasAnyRole('ADMIN','STAFF')")
 public String noShow(@PathVariable Long id,HttpServletRequest request,RedirectAttributes redirect){try{orders.recordNoShow(id);redirect.addFlashAttribute("successMessage","Đã xử lý quá hẹn theo tình trạng thanh toán; đơn đã trả tiền được chuyển sang cần xử lý");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return back(id,request);}
 @PostMapping("/orders/{id}/request-cancellation")
 public String cancellation(@PathVariable Long id,@RequestParam String reason,RedirectAttributes redirect){try{orders.requestCancellation(id,reason);redirect.addFlashAttribute("successMessage","Chi nhánh đã tiếp nhận yêu cầu hỗ trợ; đơn chưa tự hủy");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/orders";}
 @PostMapping({"/admin/orders/{id}/reconcile-cod","/staff/orders/{id}/reconcile-cod"}) @PreAuthorize("hasAnyRole('ADMIN','STAFF')")
 public String reconcile(@PathVariable Long id,@RequestParam String transactionRef,HttpServletRequest request,RedirectAttributes redirect){try{orders.reconcileCodPayment(id,null,transactionRef);redirect.addFlashAttribute("successMessage","Đã xác nhận nộp quỹ COD theo chứng từ");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return back(id,request);}
 @PostMapping({"/admin/orders/{id}/delivery-failed","/staff/orders/{id}/delivery-failed"}) @PreAuthorize("hasAnyRole('ADMIN','STAFF')")
 public String failed(@PathVariable Long id,@RequestParam String reason,HttpServletRequest request,RedirectAttributes redirect){try{orders.reportDeliveryFailed(id,reason);redirect.addFlashAttribute("successMessage","Đã ghi nhận lần giao thất bại; hàng chưa cộng lại kho");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return back(id,request);}
 @PostMapping("/admin/orders/{id}/refund-simulation") @PreAuthorize("hasRole('ADMIN')")
 public String refund(@PathVariable Long id,@RequestParam String reason,RedirectAttributes redirect){try{orders.refundSimulatedOrder(id,reason);redirect.addFlashAttribute("successMessage","Đã ghi nhận hoàn tiền mô phỏng và chứng từ; không chuyển tiền ngân hàng");}catch(BadRequestException ex){redirect.addFlashAttribute("errorMessage",ex.getMessage());}return "redirect:/admin/orders/"+id;}
}
